final class JoltWorld extends ffi.Opaque {}

final class JoltShape extends ffi.Opaque {}

final class JoltConstraint extends ffi.Opaque {}

final class JoltWorldSettings extends ffi.Struct {
  @ffi.Uint32()
  external int max_bodies;

  @ffi.Uint32()
  external int max_body_pairs;

  @ffi.Uint32()
  external int max_contact_constraints;

  @ffi.Int32()
  external int worker_threads;

  @ffi.Uint32()
  external int temp_allocator_bytes;
}

/// Simulation quality: solver iterations, sleep thresholds, allowed
/// penetration and speculative contact distance (metres).
final class JoltSolverSettings extends ffi.Struct {
  @ffi.Int32()
  external int velocity_steps;

  @ffi.Int32()
  external int position_steps;

  @ffi.Float()
  external double baumgarte;

  @ffi.Float()
  external double speculative_contact_distance;

  @ffi.Float()
  external double penetration_slop;

  @ffi.Float()
  external double time_before_sleep;

  @ffi.Float()
  external double point_velocity_sleep_threshold;

  @ffi.Bool()
  external bool allow_sleeping;
}

final class JoltBodySettings extends ffi.Struct {
  @ffi.Int32()
  external int motion_type;

  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> position;

  @ffi.Array.multi([4])
  external ffi.Array<ffi.Float> rotation;

  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> linear_velocity;

  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> angular_velocity;

  @ffi.Uint64()
  external int user_data;

  @ffi.Float()
  external double friction;

  @ffi.Float()
  external double restitution;

  @ffi.Float()
  external double linear_damping;

  @ffi.Float()
  external double angular_damping;

  @ffi.Float()
  external double gravity_factor;

  /// > 0: mass (kg) and inertia (kg m^2, 3x3 row major about the centre of
  /// mass, body axes) replace the ones Jolt computes from the shape. An
  /// all-zero inertia diagonal keeps the shape's inertia scaled to the mass.
  @ffi.Float()
  external double mass;

  @ffi.Array.multi([9])
  external ffi.Array<ffi.Float> inertia;

  @ffi.Int32()
  external int allowed_dofs;

  @ffi.Bool()
  external bool continuous_collision;

  @ffi.Bool()
  external bool start_active;

  @ffi.Bool()
  external bool is_sensor;
}

/// A contact of the last jolt_world_step (added or persisted), between the
/// sub-shapes (by user data) of two bodies. normal points from body_a to
/// body_b; impulse is the estimated normal impulse (kg m/s) of this contact.
final class JoltContact extends ffi.Struct {
  @ffi.Uint32()
  external int body_a;

  @ffi.Uint32()
  external int body_b;

  @ffi.Uint32()
  external int shape_a;

  @ffi.Uint32()
  external int shape_b;

  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> point;

  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> normal;

  @ffi.Float()
  external double impulse;

  @ffi.Float()
  external double penetration;

  @ffi.Int32()
  external int point_count;

  @ffi.Bool()
  external bool persisted;
}

final class JoltRayHit extends ffi.Struct {
  @ffi.Uint32()
  external int body;

  @ffi.Uint32()
  external int shape;

  @ffi.Float()
  external double fraction;

  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> point;

  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> normal;
}

/// How a cloth soft body is built and simulated. Compliances are inverse
/// stiffness (0 = rigid edges); a negative compliance disables that kind of
/// constraint.
final class JoltClothSettings extends ffi.Struct {
  @ffi.Float()
  external double edge_compliance;

  @ffi.Float()
  external double shear_compliance;

  @ffi.Float()
  external double bend_compliance;

  @ffi.Int32()
  external int bend_type;

  @ffi.Int32()
  external int lra_type;

  @ffi.Float()
  external double lra_max_distance_multiplier;

  @ffi.Uint32()
  external int iterations;

  @ffi.Float()
  external double linear_damping;

  @ffi.Float()
  external double max_linear_velocity;

  @ffi.Float()
  external double friction;

  @ffi.Float()
  external double restitution;

  @ffi.Float()
  external double pressure;

  @ffi.Float()
  external double vertex_radius;

  @ffi.Float()
  external double gravity_factor;

  @ffi.Bool()
  external bool update_position;

  @ffi.Bool()
  external bool allow_sleeping;

  @ffi.Bool()
  external bool double_sided;
}

/// Skinning of a cloth to a skeleton (a garment on a character). Frames are
/// the soft body's creation frame (its position / rotation), in metres.
final class JoltClothSkin extends ffi.Struct {
  /// joint_count column-major 4x4 matrices: each joint's bind pose inverted.
  external ffi.Pointer<ffi.Float> inverse_binds;

  @ffi.Uint32()
  external int joint_count;

  /// Four joints and weights per vertex (a weight of 0 ends a vertex's list).
  external ffi.Pointer<ffi.Uint32> joints;

  external ffi.Pointer<ffi.Float> weights;

  /// Per vertex: how far (m) it may move from its skinned position (0 hard
  /// skins it), and the backstop distance behind it (>= max distance: none).
  external ffi.Pointer<ffi.Float> max_distances;

  external ffi.Pointer<ffi.Float> backstop_distances;

  @ffi.Float()
  external double backstop_radius;
}

/// A ball-and-socket joint with a swing cone and a twist range. Frames are in
/// each body's local space relative to its centre of mass: the twist axis is
/// the joint frame's X axis, the plane axis its Y axis. plane_half_cone is the
/// swing about Y, normal_half_cone the swing about Z (radians).
final class JoltSwingTwistSettings extends ffi.Struct {
  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> position_a;

  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> twist_axis_a;

  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> plane_axis_a;

  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> position_b;

  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> twist_axis_b;

  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> plane_axis_b;

  @ffi.Float()
  external double normal_half_cone;

  @ffi.Float()
  external double plane_half_cone;

  @ffi.Float()
  external double twist_min;

  @ffi.Float()
  external double twist_max;

  @ffi.Float()
  external double max_friction_torque;
}

/// A hinge about the frame's X axis (hinge axis), the Y axis as the normal
/// that is 0 rad; limits in radians (min > max = no limits).
final class JoltHingeSettings extends ffi.Struct {
  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> position_a;

  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> hinge_axis_a;

  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> normal_axis_a;

  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> position_b;

  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> hinge_axis_b;

  @ffi.Array.multi([3])
  external ffi.Array<ffi.Float> normal_axis_b;

  @ffi.Float()
  external double limit_min;

  @ffi.Float()
  external double limit_max;

  @ffi.Float()
  external double max_friction_torque;
}

const int JOLT_BODY_STATE_STRIDE = 17;
